package dev.myjarvis.core;

import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

/** Real PostgreSQL transactions with an explicit synthetic database-clock seam, never sleeps. */
class ScheduleWorkerTest extends ReminderTestSupport {
    @Test void notYetDueCreatesNoOccurrenceOrJob(){UUID id=create("ONCE");assertEquals(0,workerAt(due(id).minusNanos(1)).plan(owner));assertEquals(0,count("schedule_occurrences"));assertEquals(0,count("reminder_jobs"));}
    @Test void repeatedAndParallelPlannersCreateOneUniqueOccurrence() throws Exception{UUID id=create("ONCE");var worker=workerAt(due(id));try(var pool=Executors.newFixedThreadPool(2)){var futures=pool.invokeAll(List.<Callable<Integer>>of(()->worker.plan(owner),()->worker.plan(owner)),30,TimeUnit.SECONDS);int total=0;for(var future:futures){assertFalse(future.isCancelled());total+=future.get();}assertEquals(1,total);}assertEquals(0,worker.plan(owner));assertEquals(1,count("schedule_occurrences"));assertEquals(1,count("reminder_jobs"));assertNull(due(id));}
    @Test void twoWorkersAndRepeatedSettlementCreateOneInboxRecord() throws Exception{UUID id=create("ONCE");Instant now=due(id);var a=workerAt(now);var b=workerAt(now);a.plan(owner);List<ScheduleWorker.Lease> leases=new ArrayList<>();try(var pool=Executors.newFixedThreadPool(2)){for(var future:pool.invokeAll(List.<Callable<List<ScheduleWorker.Lease>>>of(()->a.claim(owner,10),()->b.claim(owner,10)),30,TimeUnit.SECONDS)){assertFalse(future.isCancelled());leases.addAll(future.get());}}assertEquals(1,leases.size());assertTrue(a.settle(leases.getFirst()));assertFalse(b.settle(leases.getFirst()));assertEquals(1,count("notifications"));assertEquals(1,db.queryForObject("SELECT delivered_count FROM schedule_authorizations",Integer.class));}
    @Test void expiredLeaseTakeoverFencesOldGeneration(){UUID id=create("ONCE");Instant now=due(id);var a=workerAt(now);a.plan(owner);var old=a.claim(owner,10).getFirst();db.update("UPDATE reminder_jobs SET lease_until=? WHERE id=?",ScheduleService.stamp(now),old.job());var b=workerAt(now.plusSeconds(1));var replacement=b.claim(owner,10).getFirst();assertTrue(replacement.generation()>old.generation());assertFalse(a.settle(old));assertTrue(b.settle(replacement));assertEquals(1,count("notifications"));}
    @Test void expiredLeaseCannotSettleWithoutTakeover(){UUID id=create("ONCE");Instant now=due(id);var worker=workerAt(now);worker.plan(owner);var lease=worker.claim(owner,10).getFirst();db.update("UPDATE reminder_jobs SET lease_until=? WHERE id=?",ScheduleService.stamp(now),lease.job());assertFalse(worker.settle(lease));assertEquals(0,count("notifications"));}
    @Test void operationalLeaseRetriesAreBounded(){UUID id=create("ONCE");Instant now=due(id);var worker=workerAt(now);worker.plan(owner);for(int attempt=1;attempt<=3;attempt++){var lease=worker.claim(owner,10).getFirst();assertEquals(attempt,lease.generation());db.update("UPDATE reminder_jobs SET lease_until=? WHERE id=?",ScheduleService.stamp(now),lease.job());}assertTrue(worker.claim(owner,10).isEmpty());assertEquals("BLOCKED",db.queryForObject("SELECT status FROM schedule_occurrences",String.class));assertEquals("OPERATIONAL_FAILURE",db.queryForObject("SELECT reason_code FROM schedule_occurrences",String.class));assertEquals(0,count("notifications"));}
    @Test void lateness3599And3600DeliverWhile3601Skips(){for(long late:List.of(3599L,3600L,3601L)){resetReminderDatabase();UUID id=create("ONCE");var worker=workerAt(due(id).plusSeconds(late));worker.plan(owner);var leases=worker.claim(owner,10);if(late<=3600){assertEquals(1,leases.size());assertTrue(worker.settle(leases.getFirst()));assertEquals(1,count("notifications"));}else{assertTrue(leases.isEmpty());assertEquals(0,count("notifications"));assertEquals("SKIPPED_MISSED",db.queryForObject("SELECT status FROM schedule_occurrences",String.class));assertEquals(3601L,db.queryForObject("SELECT lateness_seconds FROM schedule_occurrences",Long.class));}}}
    @Test void fractionalGraceOverflowIsSkippedWithCeiling(){UUID id=create("ONCE");var worker=workerAt(due(id).plusSeconds(3600).plusNanos(1000));worker.plan(owner);assertEquals(3601L,db.queryForObject("SELECT lateness_seconds FROM schedule_occurrences",Long.class));assertEquals(0,count("reminder_jobs"));assertEquals(0,count("notifications"));}
    @Test void multipleMissedDailySlotsNeverProduceCatchupStorm(){UUID id=create("DAILY");Instant first=due(id);var worker=workerAt(first.plusSeconds(3*86400+60));assertEquals(4,worker.plan(owner));assertEquals(3L,db.queryForObject("SELECT count(*) FROM schedule_occurrences WHERE status='SKIPPED_MISSED'",Long.class));assertEquals(1,count("reminder_jobs"));var lease=worker.claim(owner,10).getFirst();assertTrue(worker.settle(lease));assertEquals(1,count("notifications"));assertEquals(first.plusSeconds(4*86400),due(id));}
    @Test void authorizationExpiryAndQuotaOverrideGrace(){for(boolean expire:List.of(true,false)){resetReminderDatabase();UUID id=create("ONCE");Instant due=due(id);var worker=workerAt(due);worker.plan(owner);var lease=worker.claim(owner,10).getFirst();if(expire)db.update("UPDATE schedule_authorizations SET expires_at=? WHERE schedule_id=?",ScheduleService.stamp(due),id);else db.update("UPDATE schedule_authorizations SET delivered_count=max_deliveries WHERE schedule_id=?",id);assertFalse(worker.settle(lease));assertEquals(0,count("notifications"));assertEquals(expire?"AUTHORIZATION_EXPIRED":"QUOTA_EXHAUSTED",db.queryForObject("SELECT reason_code FROM schedule_occurrences",String.class));}}
    @Test void restartAfterPlanningResumesOnlyPersistedPureDatabaseWork(){UUID id=create("ONCE");Instant now=due(id);workerAt(now).plan(owner);context.close();open();var worker=workerAt(now.plusSeconds(1));var lease=worker.claim(owner,10).getFirst();assertTrue(worker.settle(lease));assertEquals(1,count("notifications"));assertEquals(0,count("jobs"));assertEquals(0,count("runs"));}
    @Test void restartAfterCommitRetainsEncryptedInboxWithoutDuplicating(){UUID id=create("ONCE");UUID notification=deliver(id);context.close();open();assertEquals("Synthetic reminder sentinel",notifications.get(session,notification).get("title"));var worker=workerAt(schedules.databaseNow().plusSeconds(300));worker.plan(owner);assertTrue(worker.claim(owner,10).isEmpty());assertEquals(1,count("notifications"));}
    @Test void plannerFailureRollsBackOccurrenceJobAndNextTime(){UUID id=create("ONCE");Instant original=due(id);db.execute("ALTER TABLE reminder_jobs ADD CONSTRAINT reminder_job_failure CHECK(false)");try{assertThrows(Exception.class,()->workerAt(original).plan(owner));assertEquals(0,count("schedule_occurrences"));assertEquals(0,count("reminder_jobs"));assertEquals(original,due(id));}finally{db.execute("ALTER TABLE reminder_jobs DROP CONSTRAINT reminder_job_failure");}}
    @Test void deliveryAuditFailureRollsBackInboxCounterAndSettlement(){UUID id=create("ONCE");var worker=workerAt(due(id));worker.plan(owner);var lease=worker.claim(owner,10).getFirst();db.execute("ALTER TABLE audit_events ADD CONSTRAINT reminder_delivery_failure CHECK(event_type<>'REMINDER_INBOX_CREATED')");try{assertThrows(Exception.class,()->worker.settle(lease));assertEquals(0,count("notifications"));assertEquals(0,db.queryForObject("SELECT delivered_count FROM schedule_authorizations",Integer.class));assertEquals("PLANNED",db.queryForObject("SELECT status FROM schedule_occurrences",String.class));}finally{db.execute("ALTER TABLE audit_events DROP CONSTRAINT reminder_delivery_failure");}assertTrue(worker.settle(lease));assertEquals(1,count("notifications"));}
    @Test void pauseBeforeDeliveryCommitsPreventsEffectUnderOwnerLock() throws Exception{UUID id=create("ONCE");var worker=workerAt(due(id));worker.plan(owner);var lease=worker.claim(owner,10).getFirst();CountDownLatch entered=new CountDownLatch(1);try(var pool=Executors.newSingleThreadExecutor()){var pending=new java.util.concurrent.atomic.AtomicReference<Future<Boolean>>();schedules.writeTx.executeWithoutResult(tx->{schedules.lockOwner(owner);pending.set(pool.submit(()->{entered.countDown();return worker.settle(lease);}));try{assertTrue(entered.await(5,TimeUnit.SECONDS));}catch(InterruptedException e){throw new IllegalStateException(e);}flow.pause(session,true);});assertFalse(pending.get().get(15,TimeUnit.SECONDS));}assertEquals(0,count("notifications"));assertEquals("PAUSED",db.queryForObject("SELECT reason_code FROM schedule_occurrences",String.class));}
    @Test void committedDeliverySurvivesLaterPauseAndDisable(){UUID id=create("ONCE");UUID notification=deliver(id);flow.pause(session,true);session=auth.find(token);schedules.disable(session,UUID.randomUUID(),id,body(Map.of("expected_version",1)));assertEquals("CREATED",notifications.get(session,notification).get("status"));assertEquals(1,count("notifications"));}
    @Test void disableAndReplacementFenceOldPendingLeases(){for(boolean replace:List.of(false,true)){resetReminderDatabase();UUID id=create("DAILY");var worker=workerAt(due(id));worker.plan(owner);var lease=worker.claim(owner,10).getFirst();if(replace)confirm(preview("REPLACE",id,1L,definition("DAILY")),UUID.randomUUID());else schedules.disable(session,UUID.randomUUID(),id,body(Map.of("expected_version",1)));assertFalse(worker.settle(lease));assertEquals("CANCELLED",db.queryForObject("SELECT status FROM schedule_occurrences",String.class));assertEquals(replace?"REPLACED":"DISABLED",db.queryForObject("SELECT reason_code FROM schedule_occurrences",String.class));assertEquals(0,count("notifications"));}}
    @Test void resumedOwnerCannotReviveOldEpochSchedule(){UUID id=create("DAILY");Instant fire=due(id);flow.pause(session,true);session=auth.find(token);flow.pause(session,false);session=auth.find(token);assertEquals("RECONFIRM_REQUIRED",schedules.get(session,id).get("status"));var worker=workerAt(fire);worker.plan(owner);assertTrue(worker.claim(owner,10).isEmpty());assertEquals(0,count("notifications"));assertNotNull(db.queryForObject("SELECT revoked_at FROM schedule_authorizations",Object.class));confirm(preview("REPLACE",id,1L,definition("DAILY")),UUID.randomUUID());assertEquals("ENABLED",schedules.get(session,id).get("status"));}
    @Test void logoutDoesNotRevokeConfirmedBoundedInboxAuthority(){UUID id=create("ONCE");auth.logout(session);var worker=workerAt(due(id));worker.plan(owner);assertTrue(worker.settle(worker.claim(owner,10).getFirst()));assertEquals(1,count("notifications"));}
    @Test void encryptedNotificationCopiesSurviveScheduleReplacementAndAadSwapFails(){UUID id=create("DAILY");UUID notification=deliver(id);var changed=definition("DAILY");changed.put("text","Synthetic different copy");confirm(preview("REPLACE",id,1L,changed),UUID.randomUUID());assertTrue(notifications.get(session,notification).get("text").toString().contains("private content sentinel"));String content=db.queryForObject("SELECT content_ref FROM notifications WHERE id=?",String.class,notification);assertThrows(Exception.class,()->vault.open(owner,id,"notification-content",content));assertThrows(Exception.class,()->vault.open(owner,notification,"schedule-definition:1",content));for(String table:List.of("notifications","schedule_occurrences","reminder_jobs","audit_events"))assertFalse(Json.canonical(db.queryForList("SELECT * FROM "+table)).contains("sentinel"));}
    @Test void historicalInactiveSchedulesDoNotStarveCurrentDueWork(){UUID id=create("ONCE");Instant due=due(id);for(int i=0;i<100;i++)db.update("INSERT INTO schedules(id,owner_id,version,enabled,definition_ref,definition_digest,security_epoch,next_fire_at,created_at,updated_at) SELECT ?,owner_id,version,true,definition_ref,definition_digest,security_epoch,NULL,created_at,updated_at FROM schedules WHERE id=?",UUID.randomUUID(),id);var worker=workerAt(due);assertEquals(1,worker.plan(owner));assertTrue(worker.settle(worker.claim(owner,10).getFirst()));assertEquals(1,count("notifications"));}
    @Test void compositeDatabaseReferencesRejectCrossScheduleOccurrenceBinding(){UUID first=create("ONCE"),second=create("ONCE");var worker=workerAt(due(first));worker.plan(owner);UUID occurrence=db.queryForObject("SELECT id FROM schedule_occurrences WHERE schedule_id=?",UUID.class,first);assertThrows(Exception.class,()->db.update("INSERT INTO reminder_jobs(id,owner_id,schedule_id,occurrence_id,status,available_at,created_at) VALUES (?,?,?,?,'QUEUED',clock_timestamp(),clock_timestamp())",UUID.randomUUID(),owner,second,occurrence));}
    @Test void profileTimezoneEditCannotRetimeSavedReminder(){UUID id=create("DAILY");Instant before=due(id);context.getBean(OwnerProfileService.class).patch(session,UUID.randomUUID(),body(Map.of("expected_version",1,"timezone","Asia/Seoul")));assertEquals(before,due(id));assertEquals(1L,schedules.get(session,id).get("version"));assertEquals("UTC",((tools.jackson.databind.JsonNode)schedules.get(session,id).get("definition")).get("timezone").asText());}
    @Test void sharedApiaCatchupVectorQueuesLatestOnlyAndRetainsEarlierMetadata() throws Exception {
        var vectors=Json.parse(java.nio.file.Files.readAllBytes(java.nio.file.Path.of("../../packages/contracts/fixtures/schedules-inbox/catch-up-vectors.json")));
        for(var vector:vectors){UUID id=createAt(vector.get("definition"),Instant.parse(vector.get("issued_at").asText()));var worker=workerAt(Instant.parse(vector.get("now").asText()));worker.plan(owner);var leases=worker.claim(owner,10);assertEquals(1,leases.size());assertTrue(worker.settle(leases.getFirst()));var rows=db.queryForList("SELECT * FROM schedule_occurrences WHERE schedule_id=? ORDER BY planned_fire_at",id);assertEquals(vector.get("expected").size(),rows.size());
            for(int i=0;i<rows.size();i++){var actual=rows.get(i);var expected=vector.get("expected").get(i);assertEquals(expected.get("planned_fire_at_utc").asText(),ScheduleService.iso(actual.get("planned_fire_at")));assertEquals(expected.get("status").asText(),actual.get("status"));assertEquals(expected.get("reason_code").isNull()?null:expected.get("reason_code").asText(),actual.get("reason_code"));assertEquals(expected.get("lateness_seconds").asLong(),ScheduleService.value(actual,"lateness_seconds"));}
            assertEquals(1,count("notifications"));
        }
    }
    @Test void newEligibleSlotFencesEarlierAlreadyLeasedWholeDateGapOccurrence() throws Exception {
        var vector=Json.parse(java.nio.file.Files.readAllBytes(java.nio.file.Path.of("../../packages/contracts/fixtures/schedules-inbox/catch-up-vectors.json"))).get(0);UUID id=createAt(vector.get("definition"),Instant.parse(vector.get("issued_at").asText()));Instant early=Instant.parse("2011-12-30T10:15:00Z"),later=Instant.parse(vector.get("now").asText());var first=workerAt(early);first.plan(owner);var lease=first.claim(owner,10).getFirst();var second=workerAt(later);second.plan(owner);assertFalse(second.settle(lease));assertEquals("SUPERSEDED_MISSED",db.queryForObject("SELECT reason_code FROM schedule_occurrences WHERE id=?",String.class,lease.occurrence()));assertTrue(second.settle(second.claim(owner,10).getFirst()));assertEquals(1,count("notifications"));
    }
    @Test void settlementCancelsSupersededSlotEvenBeforeNextPlanning() throws Exception {
        var vector=Json.parse(java.nio.file.Files.readAllBytes(java.nio.file.Path.of("../../packages/contracts/fixtures/schedules-inbox/catch-up-vectors.json"))).get(0);createAt(vector.get("definition"),Instant.parse(vector.get("issued_at").asText()));var first=workerAt(Instant.parse("2011-12-30T10:29:50Z"));first.plan(owner);var lease=first.claim(owner,10).getFirst();var later=workerAt(Instant.parse("2011-12-30T10:30:01Z"));assertFalse(later.settle(lease));assertEquals("SUPERSEDED_MISSED",db.queryForObject("SELECT reason_code FROM schedule_occurrences WHERE id=?",String.class,lease.occurrence()));assertEquals(0,count("notifications"));later.plan(owner);assertTrue(later.settle(later.claim(owner,10).getFirst()));assertEquals(1,count("notifications"));
    }
    @Test void boundedPlannerMakesProgressPastOneHundredStaleDueRows(){
        UUID live=create("ONCE");Instant fire=due(live);for(int i=0;i<100;i++)db.update("INSERT INTO schedules(id,owner_id,version,enabled,definition_ref,definition_digest,security_epoch,next_fire_at,created_at,updated_at) SELECT ?,owner_id,version,true,definition_ref,definition_digest,0,?::timestamptz-interval '1 day',created_at,updated_at FROM schedules WHERE id=?",UUID.randomUUID(),ScheduleService.stamp(fire),live);
        var worker=workerAt(fire);assertEquals(0,worker.plan(owner));assertEquals(1,worker.plan(owner));assertTrue(worker.settle(worker.claim(owner,10).getFirst()));assertEquals(1,count("notifications"));assertEquals(0L,db.queryForObject("SELECT count(*) FROM schedules WHERE security_epoch=0 AND next_fire_at IS NOT NULL",Long.class));
    }
}
